let currentLang = localStorage.getItem('furnicore_lang') || 'ru';
function t(key){ return (I18N[currentLang] && I18N[currentLang][key]) || I18N.ru[key] || key; }
const CATEGORY_I18N_KEYS={'Поролон':'catFoam','Ткань':'catFabric','Экокожа':'catEcoLeather','Кожа':'catLeather','Древесина':'catWood','Фанера':'catPlywood','ДСП':'catChipboard','Крепёж':'catFasteners','Фурнитура':'catHardware'};
function categoryLabel(cat){return t(CATEGORY_I18N_KEYS[cat]||cat)}
function langButtons(){
  return `<div class="lang-switch">
    <button type="button" onclick="setLang('ru')" class="${currentLang==='ru'?'active':''}">RU</button>
    <button type="button" onclick="setLang('en')" class="${currentLang==='en'?'active':''}">EN</button>
    <button type="button" onclick="setLang('lv')" class="${currentLang==='lv'?'active':''}">LV</button>
  </div>`;
}

function sideLangButtons(){ return `<div class="side-lang"><button type="button" onclick="setLang('ru')" class="${currentLang==='ru'?'active':''}">RU</button><button type="button" onclick="setLang('en')" class="${currentLang==='en'?'active':''}">EN</button><button type="button" onclick="setLang('lv')" class="${currentLang==='lv'?'active':''}">LV</button></div>`; }
function setLang(lang){ currentLang=lang; localStorage.setItem('furnicore_lang', lang); renderAuthBox(); renderAll(); applyI18n(); }
function applyI18n(){
  document.documentElement.lang=currentLang==='lv'?'lv':currentLang==='en'?'en':'ru'; document.title=t('appTitle');
  const qs=(s)=>document.querySelector(s);
  if(qs('.brand h1')) qs('.brand h1').textContent=t('appTitle'); if(qs('.brand p')) qs('.brand p').textContent=t('appSubtitle'); if(qs('.nav-title')) qs('.nav-title').textContent=t('section');
  const nav=document.querySelectorAll('#mainNav button'); const navKeys=['stock','orders','models','refs','settings'];let navIndex=0;nav.forEach(b=>{const span=b.querySelector('.ico');const key=b.dataset.section==='history'?'history':navKeys[navIndex++];if(key)b.innerHTML=(span?span.outerHTML:'')+' '+t(key)});
  const pairs=[['#stock .title h2','stockTitle'],['#stock .title p','stockDesc'],['#orders .title h2','orderTitle'],['#orders .title p','orderDesc'],['#models .title h2','modelTitle'],['#models .title p','modelDesc'],['#settings .title h2','settings'],['#settings .title p','settingsDesc']]; pairs.forEach(([sel,key])=>{const el=qs(sel); if(el) el.textContent=t(key);});
  const b1=qs('#stock .topbar .btn.primary'); if(b1) b1.textContent=t('addMaterial'); const b2=qs('#orders .btn.primary'); if(b2) b2.textContent=t('newOrder'); const b3=qs('#models .btn.primary'); if(b3) b3.textContent=t('newModel');
  const labelMap=[['#quickAddBox .field:nth-child(1) label','skuMaterial'],['#quickAddBox .field:nth-child(2) label','qtyWithUnit'],['#quickAddBox .field.full label','foundMaterial']]; labelMap.forEach(([sel,key])=>{const el=qs(sel); if(el) el.textContent=t(key);});
  if(typeof syncQuickOperationUI==='function')syncQuickOperationUI(); const toolBtns=document.querySelectorAll('.toolbar .btn'); if(toolBtns[0]) toolBtns[0].textContent=t('filters'); if(toolBtns[1]) toolBtns[1].textContent=t('reset');
  const si=qs('#settings h3'); if(si) si.textContent=t('exportImport'); const sp=qs('#settings p.muted'); if(sp) sp.textContent=t('jsonHint'); const sb=document.querySelectorAll('#settings .actions .btn'); if(sb[0]) sb[0].textContent=t('downloadJson'); if(sb[1]) sb[1].childNodes[0].textContent=t('uploadJson'); if(sb[2]) sb[2].textContent=t('wipe');
  renderFilters(); updateSubFilter();
  const ph={topSearchInput:'searchTop',searchInput:'searchFull',quickSku:'skuIn',quickQty:'number',loginEmail:'email',loginPassword:'password'}; Object.entries(ph).forEach(([id,key])=>{ const el=document.getElementById(id); if(el) el.placeholder=t(key); });
  const qInfo=document.getElementById('quickInfo'); if(qInfo && !document.getElementById('quickSku')?.value) qInfo.textContent=t('enterSku');
  const av=document.getElementById('appVersionBadge'); if(av) av.textContent=APP_VERSION;
  const chips=[['all','all'],['problem','problems'],['needorder','needOrder'],['out','outStock'],['low','lowStock'],['ordered','ordered'],['reserved','withReserve']]; chips.forEach(([value,key])=>{const el=qs(`#quickFilterRow [data-filter="${value}"]`);if(el)el.textContent=t(key)});
  const state=document.getElementById('stockStateFilter');if(state){const value=state.value;state.innerHTML=`<option value="">${t('any')}</option><option value="ok">${t('inStock')}</option><option value="low">${t('lowStock')}</option><option value="out">${t('outStock')}</option><option value="needorder">${t('needOrder')}</option><option value="ordered">${t('ordered')}</option>`;state.value=value}
  const stockFields=document.querySelectorAll('#proFilterPanel .filter-grid .field');const stockLabels=['status','unit','supplierFilter','purchaseFilter'];stockFields.forEach((field,i)=>{const label=field.querySelector('label');if(label&&stockLabels[i])label.textContent=t(stockLabels[i])});
  const unitFilter=document.getElementById('unitFilter');if(unitFilter?.options[0])unitFilter.options[0].textContent=t('anyUnit');const supplier=document.getElementById('supplierFilter');if(supplier)supplier.placeholder=t('supplierName');const purchase=document.getElementById('orderFilter');if(purchase)purchase.placeholder=t('purchaseNumber');const note=qs('.filter-note');if(note)note.textContent=t('filterNote');
  const back=document.getElementById('modalBackBtn');if(back)back.textContent='‹ '+t('back');const modalTitle=document.getElementById('modalTitle');if(modalTitle&&!document.getElementById('modalBackdrop')?.classList.contains('show'))modalTitle.textContent=t('addModal');
  if(typeof injectHistoryUI==='function'){injectHistoryUI();if(typeof localizeHistoryUI==='function')localizeHistoryUI();if(typeof renderSiteHistory==='function')renderSiteHistory()}
}
